                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.online_offline_customer_base as with overall_data as ( select \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, \'shopify\' as channel, pincode, city_mapped as district, email, customer_name, order_timestamp::date as order_date, order_name, quantity,rto_quant,dto_quant,cancel_quant, gross_sales,rto_sales,dto_sales,cancel_sales, discount, size, payment_channel, sku_group from snitch_db.maplemonk.fact_items_snitch where LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%eco%\' AND LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%influ%\' AND order_name NOT IN (\'2431093\',\'2422140\',\'2425364\',\'2430652\',\'2422237\',\'2420623\',\'2429832\',\'2422378\',\'2428311\',\'2429064\',\'2428204\',\'2421343\',\'2431206\',\'2430491\',\'2426682\',\'2426487\',\'2426458\',\'2423575\',\'2422431\',\'2423612\',\'2426625\',\'2428117\',\'2426894\',\'2425461\',\'2426570\',\'2423455\',\'2430777\',\'2426009\',\'2428245\',\'2427269\',\'2430946\',\'2425821\',\'2429986\',\'2429085\',\'2422047\',\'2430789\',\'2420219\',\'2428341\',\'2430444\',\'2426866\',\'2431230\',\'2425839\',\'2430980\',\'2427048\',\'2430597\',\'2420499\',\'2431050\',\'2420271\',\'2426684\',\'2428747\',\'2423523\',\'2431171\',\'2430830\',\'2425325\',\'2428414\',\'2429054\',\'2423596\') AND tags NOT IN (\'FLITS_LOGICERP\') union all select \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, marketplace_mapped as channel, \'offline\' as pincode, \'offline\' as district, email, name as customer_name, order_date, order_name, suborder_quantity as quantity, 0 as rto_quant, 0 as dto_quant, 0 as cancel_quant, selling_price as gross_sales, 0 as rto_sales, 0 as dto_sales, 0 as cancel_sales, discount, size, \'prepaid\' as payment_channel, sku_group from snitch_db.maplemonk.STORE_fact_items_offline where marketplace_mapped not like \'%WH%\' ), last_marketplace as ( select phone_no, channel, row_number() over (partition by phone_no order by order_date desc) as rn from overall_data ), customer_segmentation as ( select phone_no, case when offline_buyer > 0 and shopify_buyer > 0 then \'online+offline\' when shopify_buyer > 0 then \'online_buyer\' else \'offline_buyer\' end as customer_channel from ( select phone_no, sum(case when channel = \'shopify\' then quantity end) as shopify_buyer, sum(case when channel != \'shopify\' then quantity end) as offline_buyer from overall_data group by 1 ) ), pre_category_data as ( SELECT a.phone_no, a.order_date, LISTAGG(b.product_type, \', \') WITHIN GROUP (ORDER BY b.product_type) AS all_category FROM overall_data a left join snitch_db.maplemonk.metafields_data b on a.sku_group = b.sku_group GROUP BY phone_no, order_date ), first_purchased_category as ( select phone_no, all_category, row_number() over (partition by phone_no order by order_date asc) as rn from pre_category_data ), pincode as ( select phone_no, pincode, row_number() over (partition by phone_no order by order_date desc) as rn from overall_data ), district as ( select phone_no, district, row_number() over (partition by phone_no order by order_date desc) as rn from overall_data ), email as ( select phone_no, email, row_number() over (partition by phone_no order by order_date desc) as rn from overall_data ), first_name as ( select phone_no, INITCAP(SPLIT_PART(customer_name, \' \', 1)) AS first_name, INITCAP(SPLIT_PART(customer_name, \' \', 2)) AS last_name, row_number() over (partition by phone_no order by order_date desc) as rn from overall_data ), order_data as ( select phone_no, count(distinct case when DATEDIFF(day, order_date, CURRENT_DATE) <= 30 then order_name end) as last_1_month_orders, count(distinct case when DATEDIFF(day, order_date, CURRENT_DATE) <= 90 then order_name end) as last_3_months_orders, count(distinct case when DATEDIFF(day, order_date, CURRENT_DATE) <= 180 then order_name end) as last_6_months_orders, count(distinct case when DATEDIFF(day, order_date, CURRENT_DATE) <= 360 then order_name end) as last_12_months_orders, count(distinct order_name) as gross_orders, sum(quantity) as gross_items, sum(quantity - rto_quant - dto_quant - cancel_quant) as net_items, sum(gross_sales) as gross_revenue, sum(gross_sales - rto_sales - dto_sales - cancel_sales) as net_revenue, COALESCE(sum(gross_sales) / NULLIF(count(distinct order_name), 0), 0) as gross_aov, COALESCE((sum(dto_quant) / NULLIF(sum(quantity), 0)) * 100, 0) as return_percentage, COALESCE((sum(discount) / NULLIF(sum(discount + gross_sales), 0)) * 100, 0) as discount_percentage, COALESCE((sum(cancel_quant) / NULLIF(sum(quantity), 0)) * 100, 0) as cancel_percentage, sum(discount) as gross_discount, mode(new_size) as recommend_size, COALESCE((count(distinct case when lower(payment_channel) = \'cod\' then order_name end) / NULLIF(count(distinct order_name), 0)) * 100, 0) as cod_percentage, 100 - COALESCE((count(distinct case when lower(payment_channel) = \'cod\' then order_name end) / NULLIF(count(distinct order_name), 0)) * 100, 0) as prepaid_percentage, mode(b.product_type) as frequently_purchased_category, mode(a.sku_group) as frequently_purchased_sku_group, COALESCE(sum(gross_sales) / NULLIF(sum(quantity), 0), 0) as average_selling_price, min(order_date) as first_order_date, max(order_date) as last_order_date from (select *,CASE WHEN SIZE = \'XS\' OR SIZE = \'28\' then \'XS\' WHEN SIZE = \'S\' OR SIZE = \'30\' THEN \'S\' WHEN SIZE = \'M\' OR SIZE = \'32\' THEN \'M\' WHEN SIZE = \'L\' OR SIZE = \'34\' THEN \'L\' WHEN SIZE = \'XL\' OR SIZE = \'36\' THEN \'XL\' WHEN SIZE IN (\'XXL\', \'XXl\', \'2XL\', \'38\') THEN \'XXL\' WHEN SIZE = \'3XL\' THEN \'XL3\' WHEN SIZE = \'4XL\' THEN \'XL4\' WHEN SIZE = \'5XL\' THEN \'XL5\' WHEN SIZE = \'6XL\' THEN \'XL6\' end as new_size from overall_data ) a left join snitch_db.maplemonk.metafields_data b on a.sku_group = b.sku_group group by 1 ), pre_main_data as ( select phone_no, order_date, sum(gross_sales) from overall_data group by 1,2 ), order_timeline as ( select phone_no, order_date, row_number() over (partition by phone_no order by order_date asc) as rn from pre_main_data ), order_differences AS ( SELECT phone_no, MAX(CASE WHEN rn = 1 THEN order_date END) AS first_order_date, MAX(CASE WHEN rn = 2 THEN order_date END) AS second_order_date, MAX(CASE WHEN rn = 3 THEN order_date END) AS third_order_date FROM order_timeline WHERE rn <= 3 GROUP BY 1 ), days_diff as ( SELECT phone_no, coalesce(DATEDIFF(day, first_order_date, second_order_date),\'-1\') AS time_between_1_and_2_order, coalesce(DATEDIFF(day, second_order_date, third_order_date),\'-1\') AS time_between_2_and_3_order FROM order_differences WHERE second_order_date IS NOT NULL ), main_data as ( select d.phone_no, d.last_1_month_orders, d.last_3_months_orders, d.last_6_months_orders, d.last_12_months_orders, d.gross_orders, d.gross_items, d.net_items, d.gross_revenue, d.net_revenue, d.gross_aov, d.return_percentage, d.discount_percentage, d.cancel_percentage, d.gross_discount, coalesce(d.recommend_size,\'-1\') as recommend_size, d.cod_percentage, d.prepaid_percentage, d.frequently_purchased_category, d.frequently_purchased_sku_group, d.average_selling_price, d.first_order_date, d.last_order_date, b.pincode, c.district, coalesce(e.email,d.phone_no || \'offline@snitch\') as email, f.first_name, f.last_name, coalesce(g.time_between_1_and_2_order,-1) as time_between_1_and_2_order, coalesce(g.time_between_2_and_3_order,-1) as time_between_2_and_3_order, cs.customer_channel, datediff(day,first_order_date,last_order_date)/gross_orders as average_time_duration_between_purchase, fpc.all_category as first_purchased_categories, case WHEN Pincode LIKE \'11%\' THEN \'Delhi\' WHEN Pincode LIKE \'12%\' OR Pincode LIKE \'13%\' THEN \'Haryana\' WHEN Pincode LIKE \'14%\' OR Pincode LIKE \'15%\' THEN \'Punjab\' WHEN Pincode LIKE \'16%\' THEN \'Chandigarh\' WHEN Pincode LIKE \'17%\' THEN \'Himachal Pradesh\' WHEN Pincode LIKE \'18%\' OR Pincode LIKE \'19%\' THEN \'Jammu and Kashmir, Ladakh\' WHEN Pincode BETWEEN \'200000\' AND \'289999\' THEN \'Uttar Pradesh, Uttarakhand\' WHEN Pincode BETWEEN \'300000\' AND \'349999\' THEN \'Rajasthan\' WHEN Pincode BETWEEN \'360000\' AND \'399999\' AND Pincode NOT LIKE \'396%\' THEN \'Gujarat\' WHEN Pincode LIKE \'396%\' THEN \'Dadra & Nagar Haveli and Daman & Diu\' WHEN Pincode BETWEEN \'400000\' AND \'449999\' AND Pincode NOT LIKE \'403%\' THEN \'Maharashtra\' WHEN Pincode LIKE \'403%\' THEN \'Goa\' WHEN Pincode BETWEEN \'450000\' AND \'489999\' THEN \'Madhya Pradesh\' WHEN Pincode LIKE \'49%\' THEN \'Chhattisgarh\' WHEN Pincode LIKE \'50%\' THEN \'Telangana\' WHEN Pincode BETWEEN \'510000\' AND \'539999\' THEN \'Andhra Pradesh\' WHEN Pincode BETWEEN \'560000\' AND \'599999\' THEN \'Karnataka\' WHEN Pincode BETWEEN \'600000\' AND \'669999\' THEN \'Tamil Nadu\' WHEN Pincode LIKE \'605%\' THEN \'Puducherry\' WHEN Pincode BETWEEN \'670000\' AND \'699999\' AND Pincode NOT LIKE \'682%\' THEN \'Kerala\' WHEN Pincode LIKE \'682%\' THEN \'Lakshadweep\' WHEN Pincode BETWEEN \'700000\' AND \'749999\' AND Pincode NOT LIKE \'737%\' AND Pincode NOT LIKE \'744%\' THEN \'West Bengal\' WHEN Pincode LIKE \'737%\' THEN \'Sikkim\' WHEN Pincode LIKE \'744%\' THEN \'Andaman and Nicobar Islands\' WHEN Pincode BETWEEN \'750000\' AND \'779999\' THEN \'Odisha\' WHEN Pincode LIKE \'78%\' THEN \'Assam\' WHEN Pincode BETWEEN \'790000\' AND \'799999\' THEN \'Arunachal Pradesh\' WHEN Pincode BETWEEN \'793000\' AND \'794999\' THEN \'Meghalaya\' WHEN Pincode LIKE \'795%\' THEN \'Manipur\' WHEN Pincode LIKE \'796%\' THEN \'Mizoram\' WHEN Pincode BETWEEN \'797000\' AND \'798999\' THEN \'Nagaland\' WHEN Pincode LIKE \'799%\' THEN \'Tripura\' WHEN Pincode BETWEEN \'800000\' AND \'859999\' THEN \'Bihar, Jharkhand\' WHEN Pincode BETWEEN \'900000\' AND \'999999\' THEN \'Army Postal Service\' ELSE \'Unknown\' END AS state from order_data d left join pincode b on d.phone_no = b.phone_no left join district c on d.phone_no = c.phone_no left join email e on d.phone_no = e.phone_no left join first_name f on d.phone_no = f.phone_no left join days_diff g on d.phone_no = g.phone_no left join customer_segmentation cs on d.phone_no = cs.phone_no left join first_purchased_category fpc on d.phone_no = fpc.phone_no where b.rn=1 and c.rn=1 and e.rn=1 and f.rn=1 and fpc.rn = 1 ) select a.*,case when a.customer_channel in (\'offline_buyer\',\'online+offline\') then b.channel else \'online\' end as channel from main_data a left join last_marketplace b on a.phone_no = b.phone_no where b.rn = 1 ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

